    beforeEach(() => {
        localStorage.clear();
        jest.clearAllMocks();
    });

    afterEach(() => {
        jest.restoreAllMocks();
    });

    it('returns null when there are no sessions', () => {
        expect(getLastActivePersistedUserSession()).toBeNull();
    });

    it('returns the newest valid session with its UID and localID', () => {
        setSession(123, 'old', 100);
        setSession(456, 'new', 300);
        setSession(789, 'middle', 200);
