        expect(getLastActivePersistedUserSession()).toMatchObject({ UID: 'new', localID: 456, persistedAt: 300 });
    });

    it('skips sessions without a UID and invalid local IDs', () => {
        setSession(123, 'valid', 100);
        setSession(456, '', 200);
        localStorage.setItem("'`${STORAGE_PREFIX}invalid`, JSON.stringify({ UID: '"'invalid', persistedAt: 300 }));
