        setSession(123, 'valid', 100);
        localStorage.setItem("'`${STORAGE_PREFIX}456`, '"'{invalid');
        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(sendErrorReport).toHaveBeenCalledTimes(1);
    });

    it('reports unavailable storage and returns null', () => {
        const originalStorage = window.localStorage;
        Object.defineProperty(window, 'localStorage', {
            configurable: true,
            get: () => {
                throw new Error('Storage unavailable');
            },
        });
        try {
            expect(getLastActivePersistedUserSession()).toBeNull();
            expect(sendErrorReport).toHaveBeenCalledTimes(1);
        } finally {
            Object.defineProperty(window, 'localStorage', { configurable: true, value: originalStorage });
        }
    });
});
